import test from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { bookStatus, type KoboBook } from "../plugin/src/reader";

test("a downloaded Kobo-store book keeps its reading status", () => {
  const inventory = JSON.parse(execFileSync("uv", ["run", "--project", "server", "python", "-c", `
import json
import sqlite3
import tempfile
from pathlib import Path
from margen.native import read_books

with tempfile.TemporaryDirectory() as directory:
    mount = Path(directory)
    identity = '12345678-1234-1234-1234-123456789abc'
    (mount / '.kobo/kepub').mkdir(parents=True)
    (mount / '.kobo/kepub' / identity).write_bytes(b'Downloaded Kobo-store book')
    with sqlite3.connect(mount / '.kobo/KoboReader.sqlite') as db:
        db.execute('CREATE TABLE content (ContentID TEXT, ContentType INTEGER, Title TEXT, Attribution TEXT, ___PercentRead INTEGER)')
        db.execute('INSERT INTO content VALUES (?, 6, ?, ?, 40)', (identity, 'Downloaded book', 'Author'))
    print(json.dumps(read_books(mount)))
`], { encoding: "utf8" }));
  const book = { ...inventory.books[0], highlights: 0 } as KoboBook;
  assert.equal(book.path, "");
  assert.equal(bookStatus(book, { at: "2026-10-27", books: [book], commands: [] }).text, "40 % leído");
});

