import test from 'node:test';
import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';
import vm from 'node:vm';

const require = createRequire(new URL('../plugin/package.json', import.meta.url));
const { buildSync } = require('esbuild');
const code = buildSync({
  absWorkingDir: fileURLToPath(new URL('../plugin', import.meta.url)),
  entryPoints: ['src/main.ts'], bundle: true, write: false,
  platform: 'node', format: 'cjs', external: ['obsidian', 'electron'],
  loader: { '.svg': 'text', '.wasm': 'binary' },
}).outputFiles[0].text;

test('a persisted job that was never accepted must not permanently block creation', async () => {
  const oldId = '38499783-6382-4da2-9861-4ab41397617d';
  const calls = [];
  const stub = {
    Plugin: class {}, PluginSettingTab: class {}, ItemView: class {}, Modal: class {}, Notice: class {},
    requestUrl: async ({ url, method }) => {
      const route = new URL(url).pathname;
      calls.push(route);
      if (route.includes(oldId)) return { status: 404, json: { detail: 'Trabajo no encontrado.' } };
      if (route === '/v1/jobs' && method === 'POST') return { status: 202, json: { state: 'queued' } };
      return { status: 200, json: { state: 'complete', publication_id: 'new-edition', title: 'New edition' } };
    },
  };
  const context = { module: { exports: {} }, Buffer, structuredClone, URL,
    require: name => name === 'obsidian' ? stub : require(name) };
  vm.runInNewContext(code, context);
  const plugin = new context.module.exports.default();
  plugin.state = { activeJob: oldId, composer: {}, settings: { serverUrl: 'http://localhost', token: 'x'.repeat(40) } };
  plugin.busy = false;
  plugin.app = { workspace: { getLeavesOfType: () => [] } };
  plugin.saveData = async () => {};
  await plugin.cancelJob();
  calls.length = 0;
  await assert.doesNotReject(plugin.createPublication({}, () => {}));
  assert.ok(calls.includes('/v1/jobs'));
});

from margen import library


def test_new_receipt_overrides_an_older_absent_file_inventory():
    record = {
        "id": "edition",
        "delivery": "sent",
        "delivered_at": "2026-10-27T10:01:00+00:00",
    }
    books = {"edition": {"present": False}}
    seen = {"at": "2026-10-27T10:00:00+00:00"}
    assert library.on_kobo(record, books, seen) == "copied"

const test = require('node:test');
const assert = require('node:assert/strict');
const path = require('node:path');
const vm = require('node:vm');
const { createRequire } = require('node:module');
const { execFileSync } = require('node:child_process');
const root = path.resolve(__dirname, '..');
const pluginRequire = createRequire(path.join(root, 'plugin/package.json'));
const { build } = pluginRequire('esbuild');

test('parking a second magazine during sharing sends both before closing finishes', async () => {
  const ref = process.env.PREVIEWER_REF;
  const built = await build({
    absWorkingDir: path.join(root, 'plugin'),
    entryPoints: ['src/main.ts'], bundle: true, write: false, platform: 'node', format: 'cjs',
    external: ['obsidian', 'electron'], loader: { '.svg': 'text', '.wasm': 'binary' },
    plugins: ref ? [{ name: 'review-reference', setup(builder) {
      builder.onLoad({ filter: /plugin\/src\/.*\.ts$/ }, args => ({
        contents: execFileSync('git', ['show', `${ref}:${path.relative(root, args.path)}`], { cwd: root, encoding: 'utf8' }),
        loader: 'ts', resolveDir: path.dirname(args.path),
      }));
    } }] : [],
  });
  const stub = { Plugin: class {}, PluginSettingTab: class {}, ItemView: class {}, Modal: class {}, Notice: class {} };
  const context = { module: { exports: {} }, Buffer, structuredClone,
    require: name => name === 'obsidian' ? stub : pluginRequire(name) };
  vm.runInNewContext(built.outputFiles[0].text, context);
  const plugin = new context.module.exports.default();
  const composer = (title, draftId) => ({
    paths: [`${title}.md`], title, draftId, active: true, intent: '', preserveOrder: false,
    style: 'study', writingMode: 'original', studyAids: 'none', useAI: false, sendToKobo: true, step: 1,
  });
  plugin.state = {
    composer: composer('B', '22222222-2222-4222-8222-222222222222'),
    parked: { ...composer('A', '11111111-1111-4111-8111-111111111111'), active: false },
    parkedDrafts: [],
  };
  plugin.app = { workspace: { getLeavesOfType: () => [] } };
  plugin.saveData = async () => {};
  let acknowledge;
  const gate = new Promise(resolve => { acknowledge = resolve; });
  const received = new Set();
  plugin.api = async (_route, draft) => {
    if (draft.title === 'A') await gate;
    received.add(draft.title);
  };
  const sharing = plugin.shareParked();
  const closing = plugin.parkComposer(false);
  await new Promise(resolve => setImmediate(resolve));
  acknowledge();
  await Promise.all([sharing, closing]);
  assert.deepEqual([...received].sort(), ['A', 'B'], 'Both magazines should be shared when parking completes with a healthy server');
});

