import inspect
import json
import os
from pathlib import Path
import re
import sqlite3
import subprocess
import sys
import types
from urllib.parse import parse_qs, urlparse

import margen


ROOT = Path(__file__).resolve().parents[1]
REVISION = os.environ.get("PREVIEWER_REV")
if REVISION:
    for name in ("library", "kobo", "native"):
        fullname = "margen." + name
        source = subprocess.check_output(
            ["git", "show", f"{REVISION}:server/margen/{name}.py"], cwd=ROOT, text=True
        )
        module = types.ModuleType(fullname)
        module.__file__ = str(ROOT / "server" / "margen" / (name + ".py"))
        sys.modules[fullname] = module
        setattr(margen, name, module)
