test('a definitively absent job must not prevent all future publications', async () => {
  const missing = '00000000-0000-4000-8000-000000000001';
  const stub = {
    Plugin: class {}, PluginSettingTab: class {}, ItemView: class {}, Modal: class {}, Notice: class {},
    requestUrl: async ({ url, method }) => {
      if (url.includes(missing)) return { status: 404, json: { detail: 'Trabajo no encontrado.' } };
      if (method === 'POST') return { status: 202, json: { state: 'queued' } };
      if (url.includes('/v1/jobs/')) return { status: 200, json: { state: 'complete', message: 'Done', publication_id: 'result' } };
      return { status: 200, json: { id: 'result' } };
    },
  };
  const context = {
    module: { exports: {} }, Buffer, structuredClone, URL, ArrayBuffer,
    require: name => name === 'obsidian' ? stub : pluginRequire(name),
  };
  vm.runInNewContext(code, context);
  const plugin = new context.module.exports.default();
  plugin.state = {
    activeJob: missing,
    settings: { serverUrl: 'http://localhost:8765', token: 'x'.repeat(24) },
