import test from "node:test";
import assert from "node:assert/strict";
import { promises as fs } from "node:fs";
import os from "node:os";
import path from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
import vm from "node:vm";

const root = fileURLToPath(new URL("../", import.meta.url));
const require = createRequire(new URL("../plugin/package.json", import.meta.url));
const { buildSync } = require("esbuild");
const code = buildSync({
  absWorkingDir: root, entryPoints: ["plugin/src/installation.ts"], bundle: true,
  write: false, platform: "node", format: "cjs",
}).outputFiles[0].text;
const context = { module: { exports: {} }, require, Buffer };
vm.runInNewContext(code, context);
const { installPluginFiles, recoverPluginUpdate } = context.module.exports;

test("an interrupted rollback after activation fails must remain recoverable", async () => {
  const directory = await fs.mkdtemp(path.join(os.tmpdir(), "prelo-rollback-probe-"));
  const names = ["main.js", "styles.css", "manifest.json"];
  const originalRename = fs.rename;
  try {
    for (const name of names) await fs.writeFile(path.join(directory, name), "old:" + name);
    const files = Object.fromEntries(names.map(name => [name, new TextEncoder().encode("new:" + name).buffer]));
    const transaction = await installPluginFiles(directory, files);
    assert.equal(await recoverPluginUpdate(directory), false);
    fs.rename = async (source, target) => {
      if (target === path.join(directory, "styles.css"))
        throw Object.assign(new Error("Synthetic rollback write failure"), { code: "EIO" });
      return originalRename(source, target);
    };
    await assert.rejects(transaction.rollback(), /Synthetic rollback write failure/);
    fs.rename = originalRename;
    assert.equal(await recoverPluginUpdate(directory), true,
      "Startup must recover the mixed file set left by the interrupted activation rollback");
    for (const name of names)
      assert.equal(await fs.readFile(path.join(directory, name), "utf8"), "old:" + name);
  } finally {
    fs.rename = originalRename;
    await fs.rm(directory, { recursive: true, force: true });
  }
});

