}).outputFiles[0].text;

test('a persisted job that was never accepted must not permanently block creation', async () => {
  const oldId = '38499783-6382-4da2-9861-4ab41397617d';
  const calls = [];
  const stub = {
    Plugin: class {}, PluginSettingTab: class {}, ItemView: class {}, Modal: class {}, Notice: class {},
    requestUrl: async ({ url, method }) => {
      const route = new URL(url).pathname;
      calls.push(route);
      if (route.includes(oldId)) return { status: 404, json: { detail: 'Trabajo no encontrado.' } };
      if (route === '/v1/jobs' && method === 'POST') return { status: 202, json: { state: 'queued' } };
      return { status: 200, json: { state: 'complete', publication_id: 'new-edition', title: 'New edition' } };
    },
  };
  const context = { module: { exports: {} }, Buffer, structuredClone, URL,
    require: name => name === 'obsidian' ? stub : require(name) };
  vm.runInNewContext(code, context);
  const plugin = new context.module.exports.default();
  plugin.state = { activeJob: oldId, composer: {}, settings: { serverUrl: 'http://localhost', token: 'x'.repeat(40) } };
  plugin.busy = false;
  plugin.app = { workspace: { getLeavesOfType: () => [] } };
  plugin.saveData = async () => {};
  await plugin.cancelJob();
  calls.length = 0;
  await assert.doesNotReject(plugin.createPublication({}, () => {}));
  assert.ok(calls.includes('/v1/jobs'));
});

